const category = (name: string): ExpenseCategory => ({ id: name.toLowerCase(), name, created_at: '2026-11-01T10:00:00' });
const ALUGUEL = category('Aluguel');
const LUZ = category('Luz');

const expense = (id: string, payment_date: string, cat: ExpenseCategory | null = null): Expense => ({
  id,
  category_id: cat?.id ?? null,
  description: `Despesa ${id}`,
  amount: '100.00',
  payment_date,
  is_recurring: false,
  created_at: '2026-11-01T10:00:00',
  updated_at: '2026-11-01T10:00:00',
  category: cat,
});

const E1 = expense('e1', '2026-11-20', ALUGUEL);
const E2 = expense('e2', '2026-11-10', LUZ);

const NO_PERIOD: Period = { start: '', end: '' };

async function loadedExpenses(list: Expense[] = [E1, E2], period: Period = NO_PERIOD) {
  mocked.get.mockResolvedValue({ data: list });
  const hook = renderHook((p: Period) => useAdminExpenses(p), { initialProps: period });
  await waitFor(() => expect(hook.result.current.status).toBe('ready'));
  return hook;
}

async function loadedCategories(list: ExpenseCategory[] = [ALUGUEL, LUZ]) {
  mocked.get.mockResolvedValue({ data: list });
  const hook = renderHook(() => useExpenseCategories());
  await waitFor(() => expect(hook.result.current.status).toBe('ready'));
  return hook;
}

const ids = (list: { id: string }[]) => list.map((item) => item.id);

