      <label className={styles.check}>
        <input
          type="checkbox"
          checked={fields.recurring}
          onChange={(e) => setFields((current) => ({ ...current, recurring: e.target.checked }))}
        />{' '}
        Despesa recorrente
      </label>
    </AdminForm>
  );
};

export default ExpenseForm;
