    type('Novo nome de Aluguel', 'Imóvel');
    click('Salvar', aluguel);

    expect(await screen.findByText('Categoria renomeada.')).toBeTruthy();
    expect(within(row('Aluguel de novembro')).getByText('Imóvel')).toBeTruthy();
  });
});
